input.command:
cat -A data/calibration.tsv | head -3; cat data/devices.tsv | head
cat > tests/calib_test.sh <<'EOF'
#!/bin/bash
fail=0
f=$(mktemp)
co() { LOANS=$f bash bin/checkout "$@" 2>&1; }
# expired (OSC-2 due 2026-10-31): refused, not recorded
co OSC-2 t 2026-11-01 >/dev/null && { echo "expired should fail"; fail=1; }
# unlisted device: refused
co XXX-9 t 2026-11-01 >/dev/null && { echo "unlisted should fail"; fail=1; }
[ -s "$f" ] && { echo "refused loans must not be recorded"; fail=1; }
# due date itself is OK
co OSC-2 t 2026-10-31 >/dev/null || { echo "due day should pass"; fail=1; }
[ "$(wc -l < "$f")" -eq 1 ] || { echo "due day recorded"; fail=1; }
# valid
co OSC-1 t 2026-11-01 >/dev/null || { echo "valid should pass"; fail=1; }
rm -f "$f"
exit $fail
EOF
bash tests/calib_test.sh
